#!/usr/bin/env bash
# Count the words in a sentence.
echo "the quick brown fox" | wc -w > wordcount.txt

#!/usr/bin/env python3
lines = ['banana', 'apple', 'cherry']
with open('sorted.txt', 'w') as fh:
    for l in sorted(lines):
        fh.write(l + '\n')

